import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BXzK3EA4.js";const n="/assets/image%20(34).jMa0M-YJ.png",r="/assets/image%20(35).C-mucvo0.png",f=JSON.parse('{"title":"Upstox","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/upstox.md","filePath":"connect-brokers/brokers/upstox.md"}'),i={name:"connect-brokers/brokers/upstox.md"};function p(c,e,d,l,g,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="upstox" tabindex="-1">Upstox <a class="header-anchor" href="#upstox" aria-label="Permalink to &quot;Upstox&quot;">​</a></h1><p>Upstox, a leading online stock trading platform in India, offers a comprehensive suite of services for traders and investors alike. Catering to the evolving needs of the fintech ecosystem, Upstox extends a robust API interface to developers and fintech startups keen on embedding or leveraging algorithmic trading solutions. This API facilitates the automation of trading strategies, grants access to live market data, and supports a myriad of other financial services functions.</p><p>Initiating integration with Upstox&#39;s API generally involves several key steps:</p><h3 id="generating-api-key-and-api-secret" tabindex="-1">Generating API Key and API Secret <a class="header-anchor" href="#generating-api-key-and-api-secret" aria-label="Permalink to &quot;Generating API Key and API Secret&quot;">​</a></h3><p><strong>API Key Registration</strong>: Developers must register for an API key through Upstox Accounts - Developer Apps portal, which serves as the authentication mechanism for API requests.</p><p>Goto the <a href="https://account.upstox.com/developer/apps" target="_blank" rel="noreferrer">Upstox Accounts - Developer Apps</a> Portal and login with your upstox login credentials. </p><p>Press Create New App and </p><p>Enter the App name, Redirect the URL and select I accept the terms and conditions check box, and press the Done button</p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p>API Key and API Secret Key generated for the app Tradeboard</p><figure><img src="'+r+`" alt=""><figcaption></figcaption></figure><p>Save the generated apikey and apisecret. Later we will be adding the apikey in the <a href="https://docs.algo.wesoftcorp.com/getting-started/windows-installation/environmental-variables" target="_blank" rel="noreferrer">environmental variable</a> along with the redirect url</p><p>Here is a sample of how the details would appear in a .env file for reference:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_api_key_here&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_api_secret_here&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/upstox/callback&#39;</span></span></code></pre></div><p>Integrating Tradeboard with Upstox&#39;sAPI opens up possibilities for automated trading strategies, providing a powerful tool for traders and developers to exploit market opportunities efficiently. It&#39;s essential to follow best practices for API integration, including handling rate limits, managing API keys securely, and ensuring robust error handling and logging mechanisms are in place.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/upstox/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>BCD</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code>, <code>GLOBAL_INDEX</code></li></ul>`,18)])])}const m=t(i,[["render",p]]);export{f as __pageData,m as default};
